const state={pipelines:[],current:null,config:null,stores:[],aiProvider:null,objectStorage:null,account:null,team:{members:[],roles:{}},operations:null,activity:[],notifications:{notifications:[],unread_count:0},dashboard:{counters:{},issues:[]},dialogStage:null,imageSelection:[],pipelineSearch:'',pipelineFilter:'all',taskFilter:'all'};
const stages=[
  {n:1,title:'1688 采集',desc:'AlphaShop 实时详情 · 原始商品与 SKU'},
  {n:2,title:'类目映射',desc:'实时 OZON 类目树 · 合法字典值'},
  {n:3,title:'俄语本地化',desc:'可选原图翻译或 AI 生图 · 俄语文案与 Rich Content'},
  {n:4,title:'Payload 组装',desc:'汇率、尺寸与全量属性门禁'},
  {n:5,title:'提交追踪',desc:'默认预演 · task_id 与回查'}
];
const $=selector=>document.querySelector(selector);
async function api(path,options={}){const response=await fetch(path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});const raw=await response.text();let data;try{data=raw?JSON.parse(raw):{}}catch{const preview=raw.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim().slice(0,160);throw new Error(`HTTP ${response.status} 返回非 JSON${preview?`：${preview}`:''}`)}if(!response.ok)throw new Error(data.error||`HTTP ${response.status}`);return data}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=`toast show${error?' error':''}`;clearTimeout(el.timer);el.timer=setTimeout(()=>el.className='toast',3500)}
function escapeHtml(value){return String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function stageStatus(pipeline,n){return pipeline?.stages?.[String(n)]?.status||'LOCKED'}
function formatDate(value){if(!value)return '—';const date=new Date(value);if(Number.isNaN(date.getTime()))return String(value);return new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(date)}
function hasPermission(permission){return(state.account?.identity?.permissions||[]).includes(permission)}
function canRun(n){if(stageStatus(state.current,n)==='RUNNING')return false;const permission=n===1?'pipeline.create':n===3?'images.manage':n===5?'listing.publish':'stage.run';if(!hasPermission(permission))return false;if(n===1)return true;if(n===2&&!state.stores.length)return false;return stageStatus(state.current,n-1)==='PASS'}
function selectedStoreId(){return state.current?.store_id||state.stores[0]?.store_id||''}
function storeOptions(selected=selectedStoreId()){if(!state.stores.length)return '<option value="">请先授权 OZON 店铺</option>';return state.stores.map(store=>`<option value="${escapeHtml(store.store_id)}" ${store.store_id===selected?'selected':''}>${escapeHtml(store.name)} · ${escapeHtml(store.currency_code)}</option>`).join('')}
function pipelineBucket(p){const values=Object.values(p.stages||{}).map(stage=>stage.status);const done=values.filter(status=>status==='PASS').length;if(done===5)return'completed';if(values.includes('RUNNING'))return'running';if(values.includes('FAIL'))return'failed';return'draft'}
function renderList(){const root=$('#pipelineList');const query=state.pipelineSearch.toLowerCase();const filtered=state.pipelines.filter(p=>(!query||String(p.pipeline_id).toLowerCase().includes(query))&&(state.pipelineFilter==='all'||pipelineBucket(p)===state.pipelineFilter));$('#pipelineCount').textContent=`${filtered.length} / ${state.pipelines.length} 个任务`;if(!filtered.length){root.innerHTML=`<div class="empty">${state.pipelines.length?'没有符合条件的商品任务。':'暂无商品任务，输入 1688 商品 ID 开始。'}</div>`;return}root.innerHTML=filtered.map(p=>{const done=Object.values(p.stages||{}).filter(s=>s.status==='PASS').length;const bucket=pipelineBucket(p);const bucketName={completed:'已完成',failed:'需要处理',running:'运行中',draft:'处理中'}[bucket];return `<div class="pipeline-item ${state.current?.pipeline_id===p.pipeline_id?'active':''}" data-id="${escapeHtml(p.pipeline_id)}"><span class="pipeline-dot ${done===5?'done':''}"></span><span class="pipeline-info"><b>${escapeHtml(p.pipeline_id)}</b><small>${formatDate(p.updated_at)} · ${bucketName}</small></span><span class="pipeline-progress">${done}/5</span></div>`}).join('');root.querySelectorAll('.pipeline-item').forEach(el=>el.onclick=()=>selectPipeline(el.dataset.id))}
function renderDetail(){if(!state.current){$('#emptyState').classList.remove('hidden');$('#detail').classList.add('hidden');return}$('#emptyState').classList.add('hidden');$('#detail').classList.remove('hidden');$('#productId').textContent=`1688 · ${state.current.pipeline_id}`;$('#productTitle').textContent='商品上架流水线';const selected=state.stores.find(store=>store.store_id===state.current.store_id);const statuses=stages.map(stage=>stageStatus(state.current,stage.n));const done=statuses.filter(status=>status==='PASS').length;const failed=statuses.includes('FAIL');const running=statuses.includes('RUNNING');const overall=$('#overallState');overall.textContent=failed?'需要处理':running?'正在运行':done===5?'上架完成':`${done}/5 已通过`;overall.className=`health-pill ${failed?'bad':running?'running':done===5?'good':''}`;$('#progressMetric').textContent=`${done} / 5`;$('#progressHint').textContent=done===5?'全部阶段已通过':failed?'存在门禁失败':`下一步：阶段 ${Math.min(done+1,5)}`;$('#storeMetric').textContent=selected?selected.name:state.stores.length?`${state.stores.length} 个店铺`:'未授权';$('#modeMetric').textContent=state.config?.dry_run?'DRY RUN':'LIVE';$('#modeHint').textContent=state.config?.dry_run?'安全预演，不提交':'允许真实提交';$('#updatedMetric').textContent=formatDate(state.current.updated_at);$('#configStrip').innerHTML=`<span><b>运行模式</b> ${state.config?.dry_run?'DRY RUN · 安全预演':'LIVE · 允许真实提交'}</span><span><b>OZON 店铺</b> ${selected?escapeHtml(selected.name):state.stores.length?`${state.stores.length} 个已授权 · 尚未选择`:'未授权'}</span><span><b>任务目录</b> work/${escapeHtml(state.current.pipeline_id)}/</span>`;$('#stageGrid').innerHTML=stages.map(s=>{const status=stageStatus(state.current,s.n);const artifact=state.current.artifacts?.[String(s.n)];return `<article class="stage stage-${status.toLowerCase()}"><div class="stage-number">0${s.n}<span class="status ${status.toLowerCase()}">${status}</span></div><h3>${s.title}</h3><p>${s.desc}</p><div class="stage-actions"><button data-run="${s.n}" ${canRun(s.n)?'':'disabled'}>${status==='LOCKED'?'开始运行':status==='RUNNING'?'运行中':'重新运行'}</button>${artifact?`<button class="view" data-view="${s.n}">查看产物</button>`:''}${s.n===1&&artifact?'<button class="view" data-images>管理图片</button>':''}</div></article>`}).join('');document.querySelectorAll('[data-run]').forEach(button=>button.onclick=()=>openStage(Number(button.dataset.run)));document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>viewArtifact(Number(button.dataset.view)));document.querySelectorAll('[data-images]').forEach(button=>button.onclick=openImages);const issues=(state.dashboard.issues||[]).filter(issue=>String(issue.pipeline_id)===String(state.current.pipeline_id));const card=$('#diagnosisCard');card.classList.toggle('hidden',!issues.length);$('#diagnosisCount').textContent=`${issues.length} 项`;$('#diagnosisList').innerHTML=issues.map(issue=>`<article class="diagnosis-item"><span class="diagnosis-tag">${escapeHtml(issue.category)}</span><div class="diagnosis-body"><b>阶段 ${issue.stage} · ${escapeHtml(issue.message)}</b><span>建议：${escapeHtml(issue.suggestion)}</span></div><button class="diagnosis-action" data-diagnosis-stage="${issue.stage}">打开阶段</button></article>`).join('');document.querySelectorAll('[data-diagnosis-stage]').forEach(button=>button.onclick=()=>openStage(Number(button.dataset.diagnosisStage)))}

const roleName=role=>({images:'主图',detail_images:'详情图',sku_image:'SKU 图'}[role]||role);
const actionName=action=>({exclude:'排除',translate:'翻译 → Rich Content',reference_8:'参考生成共用八图',sku_main:'生成 SKU 专属主图'}[action]||action);
function renderImageGallery(){const selected=state.imageSelection.filter(item=>item.action!=='exclude').length;const aiCalls=state.imageSelection.reduce((sum,item)=>sum+(item.action==='reference_8'?8:item.action==='sku_main'?1:0),0);const translateCalls=state.imageSelection.filter(item=>item.action==='translate').length;$('#imageSelectionCount').textContent=`已处理 ${selected} / ${state.imageSelection.length} 张 · AI 生图 ${aiCalls} 次 · 翻译 ${translateCalls} 次`;$('#imageGallery').innerHTML=state.imageSelection.map((item,index)=>`<article class="image-card ${item.action!=='exclude'?'selected':'removed'}"><img src="${escapeHtml(item.url)}" alt="${escapeHtml(roleName(item.source_role))}" loading="lazy" referrerpolicy="no-referrer"><div class="image-card-body"><span>${escapeHtml(roleName(item.source_role))}${item.sku_id?` · SKU ${escapeHtml(item.sku_id)}`:''}</span><small>${escapeHtml(item.width||'?')} × ${escapeHtml(item.height||'?')} · ${escapeHtml(actionName(item.action))}</small><select class="image-action" data-image-index="${index}"><option value="exclude" ${item.action==='exclude'?'selected':''}>排除，不处理</option><option value="translate" ${item.action==='translate'?'selected':''}>俄语翻译 → Rich Content</option><option value="reference_8" ${item.action==='reference_8'?'selected':''}>作为参考生成共用八图</option>${item.source_role==='sku_image'?`<option value="sku_main" ${item.action==='sku_main'?'selected':''}>生成 SKU 专属主图</option>`:''}</select></div></article>`).join('');document.querySelectorAll('[data-image-index]').forEach(select=>select.onchange=()=>{const index=Number(select.dataset.imageIndex);if(select.value==='reference_8')state.imageSelection.forEach((item,itemIndex)=>{if(itemIndex!==index&&item.action==='reference_8')item.action='exclude'});state.imageSelection[index].action=select.value;renderImageGallery()})}
async function openImages(){try{const result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/images`);state.imageSelection=result.images||[];renderImageGallery();$('#imagesDialog').showModal()}catch(error){toast(error.message,true)}}
async function saveImages(){try{const imagePlan=state.imageSelection.map(item=>({url:item.url,action:item.action}));const result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/images`,{method:'POST',body:JSON.stringify({image_plan:imagePlan})});state.imageSelection=result.images||[];$('#imagesDialog').close();await selectPipeline(state.current.pipeline_id);toast(`图片方案已保存：AI 生图 ${result.estimated_ai_calls} 次，翻译 ${result.estimated_translation_calls} 次`)}catch(error){toast(error.message,true)}}
function renderStores(){
  $('#storeCount').textContent=state.stores.length;const root=$('#storeList');
  if(!state.stores.length){root.innerHTML='<div class="store-empty">尚未授权店铺。凭证验证成功后才能运行 OZON 类目映射。</div>';return}
  root.innerHTML=state.stores.map(store=>`<article class="store-item"><div><strong>${escapeHtml(store.name)}</strong><span>${escapeHtml(store.store_id)} · Client-Id ${escapeHtml(store.client_id)} · ${escapeHtml(store.currency_code)}</span><small>✓ 已验证 ${escapeHtml(store.verified_at||'')}</small></div><div class="store-actions"><button type="button" data-verify-store="${escapeHtml(store.store_id)}">重新验证</button><button type="button" class="danger-link" data-delete-store="${escapeHtml(store.store_id)}">删除</button></div></article>`).join('');
  root.querySelectorAll('[data-verify-store]').forEach(button=>button.onclick=()=>verifyStore(button.dataset.verifyStore));root.querySelectorAll('[data-delete-store]').forEach(button=>button.onclick=()=>deleteStore(button.dataset.deleteStore));
}
function usageLabel(key){return{products:'商品任务',stores:'授权店铺',ai_images:'AI 生图',members:'团队成员'}[key]||key}
function renderTeam(){const members=state.team.members||[];$('#teamCount').textContent=`${members.length} 人`;$('#teamList').innerHTML=members.map(member=>`<article><div class="team-avatar">${escapeHtml((member.display_name||member.username).slice(0,1).toUpperCase())}</div><div><b>${escapeHtml(member.display_name||member.username)}</b><small>${escapeHtml(member.username)} · ${escapeHtml(member.role_name)}</small></div>${member.role==='owner'?' <span class="owner-chip">所有者</span>':hasPermission('team.manage')?`<button type="button" data-delete-member="${escapeHtml(member.username)}">移除</button>`:''}</article>`).join('');$('#teamForm').classList.toggle('hidden',!hasPermission('team.manage'));document.querySelectorAll('[data-delete-member]').forEach(button=>button.onclick=()=>deleteTeamMember(button.dataset.deleteMember))}
function operationsStoreOptions(){return state.stores.length?state.stores.map(store=>`<option value="${escapeHtml(store.store_id)}">${escapeHtml(store.name)} · ${escapeHtml(store.currency_code)}</option>`).join(''):'<option value="">请先授权 Ozon 店铺</option>'}
function renderOperations(){const data=state.operations;if(!data)return;$('#operationsEmpty').classList.add('hidden');$('#operationsContent').classList.remove('hidden');const revenue=Object.entries(data.summary.revenue||{}).map(([currency,value])=>`${Number(value).toLocaleString('zh-CN')} ${currency}`).join(' / ')||'0 RUB';$('#operationsMetrics').innerHTML=[['订单',data.summary.orders,`${data.period_days} 天`],['销售额',revenue,'已排除取消订单'],['异常订单',data.summary.exceptions,'需人工检查'],['低库存',data.summary.low_stock,`可售 ≤ ${data.low_stock_threshold??5}`]].map(([label,value,hint])=>`<article><span>${label}</span><strong>${escapeHtml(value)}</strong><small>${hint}</small></article>`).join('');const warnings=data.warnings||[];$('#operationsWarnings').classList.toggle('hidden',!warnings.length);$('#operationsWarnings').innerHTML=warnings.map(item=>`<p>${escapeHtml(item)}</p>`).join('');$('#exceptionCount').textContent=`${data.exceptions.length} 单`;$('#exceptionList').innerHTML=data.exceptions.length?data.exceptions.map(order=>`<article><span>${escapeHtml(order.scheme)}</span><div><b>${escapeHtml(order.posting_number)}</b><small>${escapeHtml(order.status)} · ${escapeHtml(formatDate(order.created_at))}</small></div><strong>${escapeHtml(order.quantity)} 件</strong></article>`).join(''):'<div class="empty">当前时间范围内没有异常订单。</div>';$('#lowStockCount').textContent=`${data.low_stocks.length} 个`;$('#lowStockTable').innerHTML=data.low_stocks.length?data.low_stocks.map(item=>`<tr><td>${escapeHtml(item.offer_id)}</td><td>${item.present}</td><td>${item.reserved}</td><td><b class="stock-low">${item.available}</b></td></tr>`).join(''):'<tr><td colspan="4" class="table-empty">没有低库存 SKU</td></tr>';const profit=data.profit||{};const profitReady=profit.status==='READY';$('#profitCard').innerHTML=`<div class="data-card-head"><div><span class="eyebrow">ESTIMATED PROFIT</span><h2>预估利润</h2></div><span class="${profitReady?'profit-ready':'profit-blocked'}">${profitReady?'可计算':'待完善'}</span></div><div class="profit-value">${profitReady?`${Number(profit.estimated_profit_cny).toLocaleString('zh-CN')} CNY`:'—'}</div><p>${escapeHtml(profitReady?`总成本 ${Number(profit.total_cost_cny).toLocaleString('zh-CN')} CNY · 已含头程、佣金、退货、提现、广告和尾程`:(profit.reason||'缺少经营参数'))}</p>${profit.missing_cost_offer_ids?.length?`<small>缺采购价：${escapeHtml(profit.missing_cost_offer_ids.join('、'))}</small>`:''}`;const logistics=data.logistics_alerts||[];$('#logisticsCount').textContent=`${logistics.length} 单`;$('#logisticsList').innerHTML=logistics.length?logistics.map(order=>`<article class="logistics-${escapeHtml(order.severity)}"><span>${escapeHtml(order.scheme)}</span><div><b>${escapeHtml(order.posting_number)}</b><small>${escapeHtml(order.status)} · ${escapeHtml(formatDate(order.shipment_date))}</small></div><strong>${order.hours_left<0?`逾期 ${Math.abs(order.hours_left)}h`:`${order.hours_left}h`}</strong></article>`).join(''):'<div class="empty">未发现 24 小时内的发货风险。</div>';const procurement=data.procurement||[];$('#procurementCount').textContent=`${procurement.length} 个 SKU`;$('#procurementTable').innerHTML=procurement.length?procurement.map(item=>`<tr><td><b>${escapeHtml(item.offer_id)}</b></td><td>${item.sold_units}</td><td>${item.daily_sales}</td><td>${item.available}</td><td>${item.target_stock}</td><td><b class="stock-low">${item.reorder_quantity}</b></td><td>${item.purchase_total_cny==null?'<span class="cost-missing">缺采购价</span>':`${Number(item.purchase_total_cny).toLocaleString('zh-CN')} CNY`}</td></tr>`).join(''):'<tr><td colspan="7" class="table-empty">当前无需补货</td></tr>';$('#orderCount').textContent=`${data.orders.length} 单`;$('#ordersTable').innerHTML=data.orders.length?data.orders.map(order=>`<tr><td><b>${escapeHtml(order.posting_number)}</b></td><td><span class="scheme-chip">${escapeHtml(order.scheme)}</span></td><td>${escapeHtml(order.status)}</td><td>${order.quantity} 件 / ${order.product_count} 款</td><td>${escapeHtml(order.warehouse)}</td><td>${Number(order.revenue).toLocaleString('zh-CN')} ${escapeHtml(order.currency_code)}</td><td>${escapeHtml(formatDate(order.created_at))}</td></tr>`).join(''):'<tr><td colspan="7" class="table-empty">当前时间范围内没有订单</td></tr>';$('#stockCount').textContent=`${data.stocks.length} 个 SKU`;$('#stocksTable').innerHTML=data.stocks.length?data.stocks.map(item=>`<tr><td><b>${escapeHtml(item.offer_id)}</b></td><td>${escapeHtml(item.product_id||'—')}</td><td>${escapeHtml(item.sku||'—')}</td><td>${item.warehouses}</td><td>${item.present}</td><td>${item.reserved}</td><td class="${item.available<=5?'stock-low':''}">${item.available}</td></tr>`).join(''):'<tr><td colspan="7" class="table-empty">未读取到库存数据</td></tr>'}
async function loadOperations(){const button=$('#refreshOperationsBtn');const storeId=$('#operationsStore').value;if(!storeId){toast('请先授权并选择 Ozon 店铺',true);return}button.disabled=true;button.textContent='正在同步…';try{state.operations=await api(`/api/operations?store_id=${encodeURIComponent(storeId)}&days=${encodeURIComponent($('#operationsDays').value)}`);renderOperations();toast('订单与库存同步完成')}catch(error){toast(error.message,true)}finally{button.disabled=false;button.textContent='同步最新数据'}}
