async function openFinanceSettings(){const storeId=$('#operationsStore').value;if(!storeId){toast('请先选择 Ozon 店铺',true);return}try{const result=await api(`/api/finance-settings?store_id=${encodeURIComponent(storeId)}`);populateFinanceFields(result.settings);$('#saveFinanceBtn').classList.toggle('hidden',!hasPermission('finance.manage'));$('#financeDialog').showModal()}catch(error){toast(error.message,true)}}
function financePayload(){return{cny_to_rub_rate:Number($('#financeRate').value),commission_percent:Number($('#financeCommission').value),return_loss_percent:Number($('#financeReturns').value),withdrawal_percent:Number($('#financeWithdrawal').value),advertising_percent:Number($('#financeAdvertising').value),last_mile_percent:Number($('#financeLastMile').value),target_margin_percent:Number($('#financeTarget').value),domestic_misc_cny:Number($('#financeMisc').value),logistics_mode:$('#financeLogisticsMode').value,postal_transport:$('#financePostalTransport').value,lead_time_days:Number($('#financeLeadTime').value),safety_stock_days:Number($('#financeSafetyStock').value)}}
async function saveFinanceSettings(event){event.preventDefault();if(!hasPermission('finance.manage')){toast('当前角色无权修改经营参数',true);return}try{await api('/api/finance-settings',{method:'POST',body:JSON.stringify({store_id:$('#operationsStore').value,settings:financePayload()})});$('#financeDialog').close();toast('经营参数已保存');await loadOperations()}catch(error){toast(error.message,true)}}
async function loadPricingSettings(){const storeId=$('#pricingStore').value;if(!storeId){toast('请先选择 Ozon 店铺',true);return}try{const value=(await api(`/api/finance-settings?store_id=${encodeURIComponent(storeId)}`)).settings;$('#pricingRate').value=value.cny_to_rub_rate;$('#pricingCommission').value=value.commission_percent;$('#pricingReturns').value=value.return_loss_percent;$('#pricingWithdrawal').value=value.withdrawal_percent;$('#pricingAdvertising').value=value.advertising_percent;$('#pricingLastMile').value=value.last_mile_percent;$('#pricingTarget').value=value.target_margin_percent;$('#pricingMisc').value=value.domestic_misc_cny;$('#pricingMode').value=value.logistics_mode;$('#pricingTransport').value=value.postal_transport;toast('已读取店铺定价参数')}catch(error){toast(error.message,true)}}
function pricingPayload(){return{sale_price_cny:Number($('#pricingSale').value),purchase_cost_cny:Number($('#pricingPurchase').value),domestic_misc_cny:Number($('#pricingMisc').value),commission_percent:Number($('#pricingCommission').value),return_loss_percent:Number($('#pricingReturns').value),withdrawal_percent:Number($('#pricingWithdrawal').value),advertising_percent:Number($('#pricingAdvertising').value),last_mile_percent:Number($('#pricingLastMile').value),target_margin_percent:Number($('#pricingTarget').value),weight_g:Number($('#pricingWeight').value),length_cm:Number($('#pricingLength').value),width_cm:Number($('#pricingWidth').value),height_cm:Number($('#pricingHeight').value),cny_to_rub_rate:Number($('#pricingRate').value),logistics_mode:$('#pricingMode').value,postal_transport:$('#pricingTransport').value}}
async function calculatePricing(event){event.preventDefault();try{const result=(await api('/api/pricing/calculate',{method:'POST',body:JSON.stringify(pricingPayload())})).calculation;const fees=result.fees;$('#pricingResults').innerHTML=`<div class="pricing-result-head"><span>${escapeHtml(result.channel)}</span><small>计费重 ${Number(result.charge_weight_g).toLocaleString('zh-CN')}g · 货值 ${Number(result.goods_value_rub).toLocaleString('zh-CN')}₽</small></div><div class="pricing-hero-result"><span>建议售价</span><strong>¥${Number(result.suggested_price_cny).toLocaleString('zh-CN')}</strong><small>保本价 ¥${Number(result.break_even_price_cny).toLocaleString('zh-CN')}</small></div><div class="pricing-kpis"><article><span>单件利润</span><b>¥${Number(result.unit_profit_cny).toLocaleString('zh-CN')}</b></article><article><span>销售毛利率</span><b>${escapeHtml(result.sales_margin_percent)}%</b></article><article><span>总成本</span><b>¥${Number(result.total_cost_cny).toLocaleString('zh-CN')}</b></article></div><div class="fee-breakdown">${[['采购成本',fees.purchase_cost],['国内杂费',fees.domestic_misc],['头程物流',fees.first_mile_logistics],['平台佣金',fees.platform_commission],['退货/取消',fees.return_cancel_loss],['提现/结汇',fees.withdrawal_exchange],['广告费',fees.advertising],['尾程配送',fees.last_mile_delivery]].map(([label,value])=>`<div><span>${label}</span><b>¥${Number(value).toLocaleString('zh-CN')}</b></div>`).join('')}</div>${result.warnings.length?`<div class="pricing-warnings">${result.warnings.map(item=>`<p>${escapeHtml(item)}</p>`).join('')}</div>`:''}`;toast('定价试算完成')}catch(error){toast(error.message,true)}}
function taskStage(pipeline){for(let n=1;n<=5;n++){const status=stageStatus(pipeline,n);if(status==='FAIL'||status==='RUNNING'||status==='LOCKED')return n}return 5}
function taskStatusName(bucket){return{completed:'已完成',failed:'门禁失败',running:'运行中',draft:'待处理'}[bucket]||bucket}
function activityName(item){const path=String(item.path||'');if(path==='/api/pipelines')return'创建并采集商品';if(/\/stages\/(\d+)$/.test(path))return`运行阶段 ${path.match(/\/stages\/(\d+)$/)[1]}`;if(path.endsWith('/images'))return'保存图片处理方案';if(path==='/api/stores')return'新增店铺授权';if(/^\/api\/stores\/[^/]+$/.test(path)&&item.method==='DELETE')return'删除店铺授权';if(path.includes('/verify'))return'验证店铺授权';if(path==='/api/finance-settings')return'修改经营参数';if(path==='/api/notifications/read')return'标记失败通知已读';if(path==='/api/ai-provider')return item.method==='DELETE'?'删除 AI 配置':'修改 AI 配置';if(path==='/api/object-storage')return item.method==='DELETE'?'删除图片存储配置':'修改图片存储配置';if(path==='/api/team'||/^\/api\/team\/[^/]+$/.test(path))return'修改团队成员';return`${item.method} ${path}`}
function renderTaskCenter(){const counters=state.dashboard.counters||{};$('#taskMetrics').innerHTML=[['全部任务',counters.total||0,'所有商品流水线'],['运行中',counters.running||0,'后台任务'],['门禁失败',counters.failed||0,'需要人工处理'],['已完成',counters.completed||0,'五阶段通过']].map(([label,value,hint])=>`<article><span>${label}</span><strong>${value}</strong><small>${hint}</small></article>`).join('');const alerts=[];if(!state.stores.length)alerts.push({level:'critical',title:'尚未授权 Ozon 店铺',detail:'类目、属性和真实上架均不可用'});if(!(state.aiProvider?.text_api_key_configured&&state.aiProvider?.image_api_key_configured))alerts.push({level:'warning',title:'AI 服务配置不完整',detail:'俄语文案或 AI 生图可能无法执行'});if(counters.failed)alerts.push({level:'critical',title:`${counters.failed} 个商品存在门禁失败`,detail:'请从下方队列打开对应商品修复'});if(state.config?.dry_run)alerts.push({level:'info',title:'当前处于 DRY RUN',detail:'第五阶段只预演，不会真实提交至 Ozon'});if(!alerts.length)alerts.push({level:'success',title:'系统运行正常',detail:'暂未发现配置或流水线告警'});$('#alertCount').textContent=`${alerts.length} 项`;$('#systemAlerts').innerHTML=alerts.map(item=>`<article class="alert-${item.level}"><i></i><div><b>${escapeHtml(item.title)}</b><small>${escapeHtml(item.detail)}</small></div></article>`).join('');const rows=state.pipelines.filter(item=>state.taskFilter==='all'||pipelineBucket(item)===state.taskFilter);$('#taskCount').textContent=`${rows.length} / ${state.pipelines.length}`;$('#taskTable').innerHTML=rows.length?rows.map(item=>{const bucket=pipelineBucket(item);const done=Object.values(item.stages||{}).filter(stage=>stage.status==='PASS').length;const current=taskStage(item);const failure=item.stages?.[String(current)]?.failures?.[0]||'—';return`<tr><td><b>${escapeHtml(item.pipeline_id)}</b></td><td><span class="task-status ${bucket}">${taskStatusName(bucket)}</span></td><td><div class="mini-progress"><i class="progress-${done}"></i></div><small>${done}/5</small></td><td>阶段 ${current} · ${escapeHtml(stages[current-1]?.title||'')}</td><td class="task-problem">${escapeHtml(failure)}</td><td>${escapeHtml(formatDate(item.updated_at))}</td><td><button data-open-task="${escapeHtml(item.pipeline_id)}" data-task-stage="${current}">打开</button></td></tr>`}).join(''):'<tr><td colspan="7" class="table-empty">没有符合条件的任务</td></tr>';document.querySelectorAll('[data-open-task]').forEach(button=>button.onclick=async()=>{await selectPipeline(button.dataset.openTask);showWorkspace('products');const stage=Number(button.dataset.taskStage);if(state.current?.artifacts?.[String(stage)])await viewArtifact(stage)});if(!hasPermission('audit.read')){$('#activityCount').textContent='受限';$('#activityList').innerHTML='<div class="empty">仅所有者和管理员可查看操作审计。</div>'}else{const activities=state.activity||[];$('#activityCount').textContent=`${activities.length} 条`;$('#activityList').innerHTML=activities.length?activities.map(item=>`<article><span class="activity-outcome ${item.outcome==='SUCCESS'?'success':'failed'}"></span><div><b>${escapeHtml(activityName(item))}</b><small>${escapeHtml(item.actor)} · ${escapeHtml(formatDate(item.created_at))} · HTTP ${escapeHtml(item.status)}</small></div></article>`).join(''):'<div class="empty">暂无操作记录，新版部署后的修改操作会显示在这里。</div>'}}
async function loadTaskCenter(){try{await loadNotifications(false);if(hasPermission('audit.read'))state.activity=(await api('/api/activity?limit=100')).activities||[];renderTaskCenter()}catch(error){toast(error.message,true);renderTaskCenter()}}
const baseRenderTaskCenter=renderTaskCenter;
renderTaskCenter=function(){baseRenderTaskCenter();document.querySelectorAll('[data-open-task]').forEach(button=>{const pipeline=state.pipelines.find(item=>String(item.pipeline_id)===String(button.dataset.openTask));const failed=pipelineBucket(pipeline||{})==='failed';button.textContent=failed?'修复 / 重试':'打开';button.onclick=async()=>{await selectPipeline(button.dataset.openTask);showWorkspace('products');const stage=Number(button.dataset.taskStage);if(failed){await openStage(stage);if(stage===5)toast('第五阶段不会自动重试，请核对结果并再次人工确认')}else if(state.current?.artifacts?.[String(stage)])await viewArtifact(stage)}})};
function renderNotifications(){const inbox=state.notifications||{notifications:[],unread_count:0};const badge=$('#notificationBadge');badge.textContent=String(inbox.unread_count||0);badge.classList.toggle('has-unread',Number(inbox.unread_count)>0);const rows=inbox.notifications||[];$('#notificationList').innerHTML=rows.length?rows.map(item=>`<button class="notification-item ${item.read?'read':'unread'}" type="button" data-notification-pipeline="${escapeHtml(item.pipeline_id)}" data-notification-stage="${escapeHtml(item.stage)}"><i></i><span><b>${escapeHtml(item.title)}</b><small>${escapeHtml(item.message)}</small><em>${item.requires_manual_confirmation?'必须人工确认真实提交':escapeHtml(item.suggestion||'打开对应阶段修复')}</em></span></button>`).join(''):'<div class="empty">当前没有门禁失败通知。</div>';document.querySelectorAll('[data-notification-pipeline]').forEach(button=>button.onclick=async()=>{const pipelineId=button.dataset.notificationPipeline;const stage=Number(button.dataset.notificationStage);$('#notificationDialog').close();await selectPipeline(pipelineId);showWorkspace('products');await openStage(stage)})}
async function loadNotifications(showError=true){try{state.notifications=await api('/api/notifications');renderNotifications()}catch(error){if(showError)toast(error.message,true)}}
async function markNotificationsRead(){try{state.notifications=await api('/api/notifications/read',{method:'POST',body:JSON.stringify({all:true})});renderNotifications();toast('通知已全部标记为已读')}catch(error){toast(error.message,true)}}
function showWorkspace(view){const operations=view==='operations';const pricing=view==='pricing';const tasks=view==='tasks';$('#productShell').classList.toggle('hidden',operations||pricing||tasks);$('#operationsView').classList.toggle('hidden',!operations);$('#pricingView').classList.toggle('hidden',!pricing);$('#taskView').classList.toggle('hidden',!tasks);$('#productNav').classList.toggle('active',view==='products');$('#taskNav').classList.toggle('active',tasks);$('#operationsNav').classList.toggle('active',operations);$('#pricingNav').classList.toggle('active',pricing);if(operations){$('#operationsStore').innerHTML=operationsStoreOptions();$('#refreshOperationsBtn').disabled=!state.stores.length;$('#financeSettingsBtn').disabled=!state.stores.length||!hasPermission('finance.read');if(!state.stores.length)$('#operationsEmpty').textContent='请先回到商品工作台授权 Ozon 店铺。'}if(pricing){$('#pricingStore').innerHTML=operationsStoreOptions();$('#loadPricingSettingsBtn').disabled=!state.stores.length||!hasPermission('finance.read')}if(tasks)loadTaskCenter()}
function renderAccount(){if(!state.account)return;const account=state.account;const name=account.identity.display_name||account.identity.username;const initial=name.slice(0,1).toUpperCase();$('#accountAvatar').textContent=initial;$('#accountDialogAvatar').textContent=initial;$('#accountName').textContent=name;$('#accountDialogName').textContent=name;$('#accountPlan').textContent=account.plan.name;$('#accountRole').textContent=`${account.identity.role_name} · ${account.workspace.name}`;$('#planName').textContent=account.plan.name;$('#planPrice').textContent=`¥${Number(account.plan.monthly_price_cny).toLocaleString('zh-CN')} / 月`;$('#billingPeriod').textContent=`计费周期 ${account.period}`;$('#usageGrid').innerHTML=Object.entries(account.plan.limits).map(([key,limit])=>{const used=Number(account.usage[key]||0);const percent=Math.min(100,Math.round(used/Math.max(1,Number(limit))*100));return `<article><div><span>${usageLabel(key)}</span><b>${used} / ${limit}</b></div><progress class="usage-track" max="100" value="${percent}" aria-label="${escapeHtml(usageLabel(key))}用量 ${percent}%"></progress><small>${percent}% 已使用</small></article>`}).join('');$('#permissionList').innerHTML=(account.identity.permission_labels||[]).map(item=>`<span>✓ ${escapeHtml(item)}</span>`).join('');$('#createForm').querySelector('button[type="submit"]').disabled=!hasPermission('pipeline.create');$('#storesBtn').disabled=!hasPermission('stores.manage');$('#aiProviderBtn').disabled=!hasPermission('ai.manage');renderTeam()}
async function load(){try{const [list,config,stores,provider,dashboard,account,team]=await Promise.all([api('/api/pipelines'),api('/api/config-status'),api('/api/stores'),api('/api/ai-provider'),api('/api/dashboard'),api('/api/account'),api('/api/team')]);state.pipelines=list.pipelines;state.config=config;state.stores=stores.stores;state.aiProvider=provider.provider;state.dashboard=dashboard;state.account=account;state.team=team;$('#modeBadge').textContent=config.dry_run?'DRY RUN':'LIVE MODE';$('#modeBadge').className=`badge ${config.dry_run?'safe':'live'}`;$('#aiProviderState').textContent=state.aiProvider.text_api_key_configured&&state.aiProvider.image_api_key_configured?'✓':'0';$('#operationsStore').innerHTML=operationsStoreOptions();$('#pricingStore').innerHTML=operationsStoreOptions();if(state.current){const found=state.pipelines.find(p=>p.pipeline_id===state.current.pipeline_id);if(found)state.current=await api(`/api/pipelines/${encodeURIComponent(found.pipeline_id)}`)}renderAccount();$('#pricingNav').disabled=!hasPermission('finance.read');renderStores();renderList();renderDetail()}catch(error){toast(error.message,true)}}
async function saveTeamMember(event){event.preventDefault();try{await api('/api/team',{method:'POST',body:JSON.stringify({username:$('#memberUsername').value.trim(),display_name:$('#memberDisplayName').value.trim(),role:$('#memberRole').value})});$('#memberUsername').value='';$('#memberDisplayName').value='';await load();toast('团队成员已保存，请在服务器创建同名登录凭证')}catch(error){toast(error.message,true)}}
async function deleteTeamMember(username){if(!confirm(`确认移除团队成员 ${username}？`))return;try{await api(`/api/team/${encodeURIComponent(username)}`,{method:'DELETE'});await load();toast('团队成员已移除')}catch(error){toast(error.message,true)}}
async function selectPipeline(id){try{state.current=await api(`/api/pipelines/${encodeURIComponent(id)}`);renderList();renderDetail()}catch(error){toast(error.message,true)}}
async function viewArtifact(n){try{const value=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/artifacts/${n}`);const failures=state.current?.stages?.[String(n)]?.failures||[];$('#artifactTitle').textContent=`0${n} · ${state.current.artifacts[String(n)]}`;$('#console').textContent=`${failures.length?`门禁失败：\n- ${failures.join('\n- ')}\n\n`:''}${JSON.stringify(value,null,2)}`}catch(error){toast(error.message,true)}}
function field(label,name,value=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" value="${escapeHtml(value)}"></div>`}
function storeField(){return `<div class="field"><label for="stageStore">OZON 店铺</label><select id="stageStore" required>${storeOptions()}</select></div>`}
function categoryOptionLabel(option){const zhPath=(option.category_path_zh||[]).join(' / ');const zhType=option.type_name_zh||'';const ruPath=(option.category_path_ru||[]).join(' / ');const ruType=option.type_name_ru||'';return `${zhPath}${zhType?` · ${zhType}`:''}${ruPath?` ｜ ${ruPath}`:''}${ruType?` · ${ruType}`:''} ｜ category ${option.ozon_category_id} / type ${option.ozon_type_id}`}
async function searchOzonCategories(){const query=$('#categoryQuery').value.trim();if(query.length<2){toast('请输入至少 2 个类目关键词，例如“香薰石牌”',true);return}const button=$('#searchCategoryBtn');const select=$('#manualCategory');button.disabled=true;button.textContent='正在读取 Ozon…';select.innerHTML='<option value="">正在搜索官方类目树…</option>';try{const storeId=$('#stageStore').value;const result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/category-options?q=${encodeURIComponent(query)}&store_id=${encodeURIComponent(storeId)}`);const options=result.options||[];select.innerHTML='<option value="">请选择正确的 Ozon 官方类目 / 商品类型</option>'+options.map(option=>`<option value="${option.ozon_category_id}:${option.ozon_type_id}">${escapeHtml(categoryOptionLabel(option))}</option>`).join('');$('#categorySearchStatus').textContent=options.length?`找到 ${result.total_matches} 个匹配项，按相关度显示前 ${options.length} 个。请核对“商品类型”，不要选择香薰蜡烛。`:'没有匹配项，请尝试“香薰石”“扩香石”“香薰挂件”或俄语关键词。'}catch(error){select.innerHTML='<option value="">读取失败，请重试</option>';$('#categorySearchStatus').textContent=error.message;toast(error.message,true)}finally{button.disabled=false;button.textContent='搜索 Ozon 官方类目'}}
function attributeTextValue(value){if(Array.isArray(value))return value.join(', ');if(value&&typeof value==='object')return JSON.stringify(value);return String(value??'')}
function requiredAttributeFields(attributes){if(!attributes.length)return '<div class="warning">Ozon 当前类目没有可编辑特征。</div>';return `<div class="warning">以下是当前类目的全部 Ozon 特征（包含选填项）。字段名和字典候选值使用 Ozon 官方简体中文显示；系统内部保留同一个属性 ID，组装上架载荷时自动换成 Ozon 俄语合法值。自由文本可直接输入中文，保存第四阶段时会调用已配置的 AI 文本服务一次性译为俄语。</div>${attributes.map(attribute=>{const id=attribute.attribute_id;const required=attribute.is_required;const zhName=attribute.attribute_name_zh||`Ozon 特征 ${id}`;const ruName=attribute.attribute_name_ru||'';const label=`${required?'【必填】':'【可选】'} ${zhName} · ID ${id}`;const ruHint=ruName&&ruName!==zhName?`Ozon 俄语字段：${escapeHtml(ruName)}`:'';if(attribute.is_dictionary){const selectedId=attribute.selected_dictionary_value_id??'';const current=selectedId!==''?`<option value="${selectedId}" selected>已选择 · ID ${selectedId}</option>`:'';return `<div class="field"><label for="attribute_${id}">${escapeHtml(label)}</label><select id="attribute_${id}" data-required-attribute="${id}" data-attribute-kind="dictionary" data-is-required="${required}" data-original="${selectedId}" data-override-required="${attribute.override_required}" data-values-loaded="false"><option value="">${required?'请选择 Ozon 合法值':'留空，不提交此可选特征'}</option>${current}</select><small>${ruHint}${ruHint?' · ':''}展开时从 Ozon API 实时加载中文候选值</small></div>`}const textValue=attributeTextValue(attribute.selected_value);return `<div class="field"><label for="attribute_${id}">${escapeHtml(label)}</label><input id="attribute_${id}" data-required-attribute="${id}" data-attribute-kind="text" data-is-required="${required}" data-original="${escapeHtml(textValue)}" data-override-required="${attribute.override_required}" value="${escapeHtml(textValue)}" placeholder="${required?'请输入准确的中文特征值':'可选，可输入中文，留空则不提交'}"><small>${ruHint}${ruHint?' · ':''}新输入的中文会在载荷组装前译为俄语；已有俄语值保持不变</small></div>`}).join('')}`}
async function loadAttributeDictionary(control){if(control.dataset.valuesLoaded==='true')return;control.dataset.valuesLoaded='loading';const current=control.value;const empty=control.options[0]?.textContent||'留空';try{const result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/attributes/${encodeURIComponent(control.dataset.requiredAttribute)}/values`);control.innerHTML=`<option value="">${escapeHtml(empty)}</option>`+(result.options||[]).map(option=>`<option value="${option.dictionary_value_id}" ${String(option.dictionary_value_id)===current?'selected':''}>${escapeHtml(option.value)} · ${option.dictionary_value_id}</option>`).join('');control.dataset.valuesLoaded='true'}catch(error){control.dataset.valuesLoaded='false';toast(error.message,true)}}
async function openStage(n){state.dialogStage=n;const titles=['','采集 1688 商品','匹配 OZON 类目','生成俄语内容','组装上传 Payload','提交与追踪'];$('#dialogTitle').textContent=titles[n];let html='';if(n===1)html='<div class="warning">重新采集会调用 AlphaShop 实时详情接口，并使后续产物需要重新验证。</div>';if(n===2)html=storeField()+field('自动选择置信度阈值','threshold','0.70');if(n===3){const aiReady=state.aiProvider?.text_api_key_configured&&state.aiProvider?.image_api_key_configured;html=`<div class="warning">请先在阶段 1 的“图片”中设置每张图的用途。共用八图会调用生图模型 8 次；SKU 主图每张调用 1 次；翻译图只进入 Rich Content。</div><div class="field"><label for="mediaMode">图片处理方式</label><select id="mediaMode"><option value="image_plan" ${aiReady?'selected':''} ${aiReady?'':'disabled'}>执行逐图处理方案（推荐）</option><option value="alphashop_translate">全部使用 AlphaShop 翻译</option><option value="ai_generate" ${state.aiProvider?.image_api_key_configured?'':'disabled'}>全部逐张 AI 生图（旧模式）</option></select></div><div class="field"><label for="textMode">俄语文本方式</label><select id="textMode"><option value="built_in">内置严格规则</option><option value="ai_generate" ${aiReady?'selected':''} ${state.aiProvider?.text_api_key_configured?'':'disabled'}>AI 生成标题、描述和标签</option></select></div>${aiReady?'':`<div class="warning danger">AI 服务尚未配置完整，请先点击页面顶部“AI 服务”。</div>`}`};if(n===4){html=storeField()+field('CNY → 店铺币种汇率','rate','12.50')+field('估算尺寸：深 / 宽 / 高 / 重量(g)','dims','80 / 80 / 200 / 350')+'<div id="requiredAttributes"><div class="warning">正在读取当前类目的全部 Ozon 特征…</div></div>'}if(n===5){const blocked=state.config?.dry_run;html=`<div class="warning danger">${blocked?'服务器当前为 DRY RUN，真实提交已锁定；本次运行绝不会被标记为上架成功。请先在服务器启用 LIVE MODE。':'服务器已处于 LIVE MODE。勾选确认后才会调用 Ozon，并且只有取得 task_id、导入成功且属性回查通过才会显示 PASS。'}</div><div class="field"><label><input id="execute" type="checkbox" ${blocked?'disabled':''}> 我明确要求执行真实提交</label></div>`}$('#dialogFields').innerHTML=html;$('#stageDialog').showModal();if(n===4){try{const result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/required-attributes`);$('#requiredAttributes').innerHTML=requiredAttributeFields(result.attributes||[]);document.querySelectorAll('[data-attribute-kind="dictionary"]').forEach(control=>control.onfocus=()=>loadAttributeDictionary(control))}catch(error){$('#requiredAttributes').innerHTML=`<div class="warning danger">${escapeHtml(error.message)}</div>`;toast(error.message,true)}}}
const delay=milliseconds=>new Promise(resolve=>setTimeout(resolve,milliseconds));
async function waitForStage(n){for(let attempt=0;attempt<1200;attempt++){await delay(3000);state.current=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}`);renderList();renderDetail();const status=stageStatus(state.current,n);$('#console').textContent=`阶段 ${n} 正在后台执行… 已等待 ${Math.round((attempt+1)*3)} 秒`;if(status!=='RUNNING')return status}throw new Error(`阶段 ${n} 后台执行超过 60 分钟，请检查服务日志`)}
async function runStage(event){event.preventDefault();const n=state.dialogStage;let body={};try{if(n===2){body.confidence_threshold=Number($('#threshold').value);body.store_id=$('#stageStore').value}if(n===3){body.media_mode=$('#mediaMode').value;body.text_mode=$('#textMode').value}if(n===4){const dims=$('#dims').value.split('/').map(v=>Number(v.trim()));if(dims.length!==4||dims.some(v=>!Number.isFinite(v)||v<=0))throw new Error('尺寸必须是四个正数');const attributeOverrides={};document.querySelectorAll('[data-required-attribute]').forEach(control=>{const value=control.value.trim();if(!value&&control.dataset.isRequired==='true')throw new Error(`请填写或选择 ${control.previousElementSibling?.textContent||'Ozon 必填属性'}`);const changed=value!==String(control.dataset.original??'');if(value&&(changed||control.dataset.overrideRequired==='true'))attributeOverrides[control.dataset.requiredAttribute]=control.dataset.attributeKind==='dictionary'?{dictionary_value_id:Number(value)}:{value}});body.store_config={store_id:$('#stageStore').value,cny_to_rub_rate:$('#rate').value.trim(),dimension_defaults:{depth:dims[0],width:dims[1],height:dims[2],weight:dims[3],dimension_unit:'mm',weight_unit:'g'},vat:'0',attribute_overrides:attributeOverrides}}if(n===5){if(state.config?.dry_run)throw new Error('服务器仍为 DRY RUN，请先启用 LIVE MODE 并重启服务');if(!$('#execute').checked)throw new Error('请勾选“我明确要求执行真实提交”');body.execute=true}$('#stageDialog').close();$('#console').textContent=`正在执行阶段 ${n}…`;let result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/stages/${n}`,{method:'POST',body:JSON.stringify(body)});if(result.status==='RUNNING'){toast(`阶段 ${n} 已转入后台执行`);await selectPipeline(state.current.pipeline_id);await waitForStage(n);result={...result,status:stageStatus(state.current,n),failures:state.current.stages?.[String(n)]?.failures||[]}}const failures=result.failures||[];const details=failures.join('；');if(failures.length)$('#console').textContent=`门禁失败：\n- ${failures.join('\n- ')}`;toast(`阶段 ${n}：${result.status}${details?` · ${details}`:''}`,result.status==='FAIL');await selectPipeline(state.current.pipeline_id);if(state.current.artifacts?.[String(n)])await viewArtifact(n)}catch(error){toast(error.message,true)}}
const baseOpenStage=openStage;
const baseRunStage=runStage;
async function openStageWithCategoryPicker(n){if(n!==2)return baseOpenStage(n);state.dialogStage=2;$('#dialogTitle').textContent='匹配 OZON 类目';$('#dialogFields').innerHTML=storeField()+`<div class="warning danger">类目决定商品类型和整套 Ozon 特征。请搜索并人工确认官方类目；“香薰石牌”不能继续使用“香薰蜡烛”的类目或类型。</div><div class="field"><label for="categoryQuery">商品类目关键词（中文或俄语）</label><div class="category-search-row"><input id="categoryQuery" value="香薰石牌" placeholder="例如：香薰石牌"><button id="searchCategoryBtn" type="button">搜索 Ozon 官方类目</button></div><small id="categorySearchStatus">搜索结果来自当前授权店铺的 Ozon 实时类目树。</small></div><div class="field"><label for="manualCategory">Ozon 官方类目 / 商品类型</label><select id="manualCategory" required><option value="">请先搜索并选择正确类目</option></select></div>`+field('选择置信度阈值','threshold','0.70');$('#stageDialog').showModal();$('#searchCategoryBtn').onclick=searchOzonCategories;$('#categoryQuery').onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();searchOzonCategories()}};await searchOzonCategories()}
async function runStageWithCategoryPicker(event){if(state.dialogStage!==2)return baseRunStage(event);event.preventDefault();try{const pair=$('#manualCategory').value.split(':');if(pair.length!==2)throw new Error('请先搜索并选择正确的 Ozon 官方类目 / 商品类型');const body={confidence_threshold:Number($('#threshold').value),store_id:$('#stageStore').value,manual_category_id:Number(pair[0]),manual_type_id:Number(pair[1])};$('#stageDialog').close();$('#console').textContent='正在按人工选择的 Ozon 官方类目重新映射…';const result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/stages/2`,{method:'POST',body:JSON.stringify(body)});const failures=result.failures||[];if(failures.length)$('#console').textContent=`门禁失败：\n- ${failures.join('\n- ')}`;toast(`阶段 2：${result.status}${failures.length?` · ${failures.join('；')}`:''}`,result.status==='FAIL');await selectPipeline(state.current.pipeline_id);if(state.current.artifacts?.['2'])await viewArtifact(2)}catch(error){toast(error.message,true)}}
